    })

    // 日期格式选项（互斥）
    .addCheckbox({
        name: 'useMMDDYYYY',
        label: '美式 (MM/DD/YYYY)',
        value: false,
        onChange: function() { toggleDateFormat('useMMDDYYYY'); }
    })
    .addCheckbox({
        name: 'useDDMMYYYY',
        label: '欧式 (DD/MM/YYYY)',
        value: false,  // 默认改为 false
        onChange: function() { toggleDateFormat('useDDMMYYYY'); }
    })
    .addCheckbox({
        name: 'useYYYYMMDD',
        label: '国际标准 (YYYY/MM/DD)',
        value: true,  // 默认改为 true
        onChange: function() { toggleDateFormat('useYYYYMMDD'); }
    })

    .addText({
        name: 'delimiter',
        label: '时间分隔符',
        value: ':'
    })
    .finish();

// 互斥切换日期格式
function toggleDateFormat(selectedFormat) {
    if (scriptProperties[selectedFormat]) {
        ['useMMDDYYYY', 'useDDMMYYYY', 'useYYYYMMDD'].forEach(format => {
            if (format !== selectedFormat) scriptProperties[format] = false;
        });
    }
}

export function update(value) {
    const time = new Date();
    const pad = num => num.toString().padStart(2, '0');

    // 时间部分
    let hours = time.getHours();
    let timePeriod = '';

    if (!scriptProperties.use24hFormat) {
        timePeriod = hours >= 12 ? ' pm' : ' am';
        hours = hours % 12 || 12; // 转换为12小时制
    }

    value = [
        pad(hours),
        pad(time.getMinutes()),
        scriptProperties.showSeconds ? pad(time.getSeconds()) : null
    ].filter(Boolean).join(scriptProperties.delimiter) + timePeriod;

    // 日期部分
    if (scriptProperties.displayDate) {
        const [day, month, year] = [
            pad(time.getDate()),
            pad(time.getMonth() + 1),
            time.getFullYear()
        ];

        let dateStr;
        if (scriptProperties.useMMDDYYYY) {
            dateStr = `${month}/${day}/${year}`;       // 美式
        } else if (scriptProperties.useYYYYMMDD) {
            dateStr = `${year}/${month}/${day}`;       // 国际标准（用/分隔）
        } else {
            dateStr = `${day}/${month}/${year}`;       // 默认欧式
        }

        value += '\n' + dateStr;
    }

    return value;
}

