'use strict';

const editorInfo = [
	'Successfully loaded Noeru Script Library (NSL) v1.4.0',
	'Available components: Event Dispatcher | Timeline Animation Scheduler | Script Animation Scheduler | Simple Emoji Switcher | Swaying Animation Launcher | User Property Category Change Detector',
	'Debug Tip: A call source of “Unknown” means that the corresponding call was made before the layer was initialized.'
]

export var scriptProperties = createScriptProperties()
	.addCheckbox({
		name: 'debugMode',
		label: 'Debug Mode',
		value: false
	})
	.addCheckbox({
