	})
	.addCheckbox({
		name: 'warningAutoReRegist',
		label: 'Warning for auto re-registrations',
		value: true
	})
	.finish();

const isRunningInEditor = engine.isRunningInEditor()
let debugMode, logInterrupts, tips, globalReplayable;

if (!isRunningInEditor) {
	console.log = () => { }
}

/**
 * @param {Boolean} value - for property 'visible'
 * @return {Boolean} - update current property value
 */
export function init() {
	debugMode = isRunningInEditor && scriptProperties.debugMode
	logInterrupts = isRunningInEditor && scriptProperties.logInterrupts
	tips = isRunningInEditor && scriptProperties.tips
	globalReplayable = scriptProperties.replayableByDefault
	return false;
}


function getTargetName(obj) {
	if (obj === null) return 'Unknown'
	if (!obj.name) return 'Nameless'
	return obj.name
}

function getCallSourceInfo() {
	return '(Call from object [' + getTargetName(thisObject) + '] in layer [' + getTargetName(thisLayer) + '])'
}


/*

	Custom Events

*/

class Event {
	/**
	* @param {Hashable} eventID
	* @param {ILayer} layer
	* @param {IObject} object
	* @param {any} eventData
	*/
	constructor(eventID, eventData) {
		this.srcLayer = thisLayer;	// 由于类将在源脚本进行实例化，所以此处变量将指向调用源的父级对象
		this.srcObject = thisObject;
		this.id = eventID;
		this.data = eventData;
		this.interrupted = false;
	}

	interruptDispatch() {
		if (debugMode || logInterrupts) {
			console.log('DEBUG: Event "' + this.id + '" dispatch has been interrupted.')
		}
		this.interrupted = true
	}
}

class Listener {
	/**
	* @param {Hashable} listenerID
	* @param {ILayer} layer
	* @param {IObject} object
	* @param {any} eventData
	*/
	constructor(listenerID, callback, priority = 0, data = null) {
		this.thisLayer = thisLayer	// 由于类将在源脚本进行实例化，所以此处变量将指向调用源的父级对象
		this.thisObject = thisObject
		this.id = listenerID;
		this.callback = callback;
		this.priority = priority;
		this.data = data
	}
}

class EventType {
	/**
	* @param {Hashable} eventID
	* @param {string} eventName
	*/
	constructor(eventID, eventName = null, skipDebug = false) {
		this.id = eventID
		this.debug = !skipDebug
		this.name = eventName
		this.listeners = new Map()
		this.sortedListeners = [];
		this.sorted = false;
		this.hasListener = false
	}

	/**
	* @param {Hashable} listenerID
	* @param {function} callback
	* @param {Number} priority
	*/
	addListener(listenerID, callback, priority = 0, data = null) {
		if (this.listeners.has(listenerID)) {
			console.log('WARNING: Listener ID "' + listenerID + '" has been already registered. New Registration operation has been ignored. ' + getCallSourceInfo())
			return
		}
		this.listeners.set(listenerID, new Listener(listenerID, callback, priority, data))
		this.sorted = false
		this.hasListener = true
	}

	sortCallbacks() {
		if (this.sorted) {
			return
		}
		this.sortedListeners = Array(this.listeners.values())
		this.sortedListeners.sort((a, b) => b.priority - a.priority)
		this.sorted = true;
	}

	tryCallback(event, listener) {
		try {
			listener.callback(event, listener)
		} catch (err) {
			console.error('An error occurs when dispatching event "' + event.id + '" to listener "' + listener.id + '": ' + err)
			console.log('The listener is located in the object [' + (thisObject === null ? 'unknown' : thisObject.name) + '] in layer [' + (thisLayer === null ? 'unknown' : thisLayer.name) + '])')
			console.log('You can set the "callbackWithoutTry" property of the event dispatcher to "true" to prevent catching errors for debugging purposes.')
		}
	}

	callback(event, listener) {
		listener.callback(event, listener)
	}

	/**
	* @param {Event} event
	*/
	dispatchToAll(event) {
		if (!this.hasListener) {
			return
		}
		this.sortCallbacks()
		let cbFunc = eventDispatcher.callbackWithoutTry ? this.callback : this.tryCallback
		if (debugMode && this.debug) {
			console.log('DEBUG: Dispatching event "' + event.id + '" to listeners [ ' + Array.from(this.listeners.keys()).toString() + ' ]')
		}
		for (let listener of this.listeners.values()) {
			cbFunc(event, listener)
			if (event.interrupted) {
				break
			}
		}
	}

	/**
	* @param {Hashable} listenerID
	* @param {Event} event
	*/
	dispatchToListener(listenerID, event) {
		if (!this.hasListener) {
			return
		}
		let listener = this.listeners.get(listenerID)
		if (listener === undefined) {
			console.error('Listener ID "' + listenerID + '" does not exist. ' + getCallSourceInfo())
			return
		}
		this.sortCallbacks()
		listener.callback(event, listener)
	}
}

class EventDispatcher {
	constructor() {
		this.eventTypes = new Map()
		this.dispatching = false
		this.tasks = []
		this.callbackWithoutTry = false		// 调试时使用
	}

	/**
	* @param {Hashable} eventID
	* @param {string} eventName
	*/
	registerEvent(eventID, eventName = null, skipDebug = false) {
		if (this.eventTypes.has(eventID)) {
			return false
		}
		this.eventTypes.set(eventID, new EventType(eventID, eventName, skipDebug))
		return true
	}

	/**
	* @param {Hashable} eventID
	* @param {Hashable} listenerID
	* @param {function} callback
	* @param {Number} priority
	*/
	registerListener(eventID, listenerID, callback, priority = 0, data = null) {
		let eventType = this.eventTypes.get(eventID)
		if (eventType === undefined) {
			console.error('Event ID "' + eventID + '" does not exist. ' + getCallSourceInfo())
			return false
		}
		eventType.addListener(listenerID, callback, priority, data)
		if (debugMode && eventType.debug) {
			console.log('DEBUG: Registering listener "' + listenerID + '" to event "' + eventID + '". Current listener count: ' + eventType.listeners.size + '')
		}
		return true
	}

	/**
	* @param {Event} event
	*/
	dispatchEventToAll(event, autoWait = true, log = true) {
		let eventType = this.eventTypes.get(event.id)
		if (eventType === undefined) {
			if (log) {
				console.error('Event ID "' + event.id + '" does not exist. ' + getCallSourceInfo())
			}
			return
		}
		if (autoWait) {
			if (this.dispatching) {
				this.tasks.push([event])
				return
			}
			this.dispatching = true
			eventType.dispatchToAll(event)
			this.dispatching = false
			this.nextTask()
		} else {
			eventType.dispatchToAll(event)
		}
	}

	/**
	* @param {Hashable} listenerID
	* @param {Event} event
	*/
	dispatchEventToListener(listenerID, event, autoWait = true, log = true) {
		let eventType = this.eventTypes.get(eventID)
		if (eventType === undefined) {
			if (log) {
				console.error('Event ID "' + event.id + '" does not exist. ' + getCallSourceInfo())
			}
			return
		}
		if (autoWait) {
			if (this.dispatching) {
				this.tasks.push([listenerID, event])
				return
			}
			this.dispatching = true
			eventType.dispatchToListener(listenerID, event)
			this.dispatching = false
			this.nextTask()
		} else {
			eventType.dispatchToListener(listenerID, event)
		}
	}

	nextTask() {
		if (this.dispatching || this.tasks.length === 0) {
			return
		}
		let task = this.tasks.shift()
		if (task.length === 1) {
			this.dispatchEventToAll(task[0])
		} else {
			this.dispatchEventToListener(task[0], task[1])
		}
	}
}

let eventDispatcher = new EventDispatcher()
shared.eventDispatcher = eventDispatcher
shared.Event = Event


/*

	Animation System

*/


let needToCalcInterpolator = false


class AnimationScheduler {
	constructor() {
		this.tidCount = -1
		this.aidCount = -1
		this.aniTasks = new Map()
		this.needToMapAni = false
		this.cAniMappers = new Map()
		this.needToDelMapper = false
		this.cAniMapperDelTasks = {}	// 尚未使用，待修改为Map
		this.cAniListeners = new Map()
		this.tAniInterpolators = new Map()
		this.globalEvents = new Set()
	}

	_getTid() {
		this.tidCount += 1
		return this.tidCount
	}

	_getAid() {
		this.aidCount += 1
		return this.aidCount
	}

	setGlobalDispatching(eventName, enable = true) {
		if (enable) {
			if (!eventDispatcher.registerEvent(eventName)) {
				if (scriptProperties.warningAutoReRegist) console.log('WARNING: Event ID "' + eventName + '" has been registered in the global event dispatcher, so beware of incorrect event listeners! ' + getCallSourceInfo())
			}
			this.globalEvents.add(eventName)
		} else {
			this.globalEvents.delete(eventName)
		}
	}

	removeInterpolator(aid, callback = true) {
		let data = this.tAniInterpolators.get(aid)
		if (data === undefined) {
			return
		}
		this.tAniInterpolators.delete(aid)
		needToCalcInterpolator = this.tAniInterpolators.size !== 0
		if (callback) {
			data.srcAni.setEndSignal()
		}
	}

	addInterpolator(aid, data) {
		// 可用于替换
		this.tAniInterpolators.set(aid, data)
		needToCalcInterpolator = true
	}

	calcInterpolators() {
		let tAniData;
		let frametime = engine.frametime
		for (tAniData of this.tAniInterpolators.values()) {
			if (tAniData._addFrametime(frametime)) {
				tAniData._frameUpdate()
			} else {
				tAniData._frameUpdate()
				this.removeInterpolator(tAniData.srcAni.aid)
			}
		}
	}

	mapAnis() {
		return
		let config, data;
		for (config of this.cAniMappers.values()) {
			data = mapper[2]
			config[1](data, config[0](data))
		}
		if (this.needToDelMapper) {
			this.cAniMapperDelTasks.forEach((aid) => { if (this.cAniMapperDelTasks[aid] !== 0) { this.cAniMappers.delete(aid); delete this.cAniMapperDelTasks[aid] } else { this.cAniMapperDelTasks[aid] = 1 } })
			this.needToMapAni = this.cAniMappers.size !== 0
			this.needToDelMapper = Object.keys(this.cAniMapperDelTasks).length !== 0
		}
	}

	removeAniMapper(aid) {
		return
		this.cAniMapperDelTasks[aid] = 0
		this.needToDelMapper = true
	}

	addAniMapper(aid, config) {
		if (this.cAniMappers.has(aid)) {
			return
		}
		this.cAniMappers.set(aid, config)
		this.needToMapAni = true
	}

	addTAniInterpolator(name, interpolator, deltaFunc, equalityChecker) {
		if (name in interpolators) {
			console.error('Interpolator "' + name + '" already exists. ' + getCallSourceInfo())
			return
		}
		interpolators[name] = interpolator
		deltaFuncs[name] = deltaFunc
		equalityCheckers[name] = equalityChecker
	}

	reportEventToAniList(eventName) {
		let taskList;
		for (taskList of this.aniTasks.values()) {
			taskList.handleAnimationEvent(eventName)
		}
		if (this.globalEvents.has(eventName)) {
			eventDispatcher.dispatchEventToAll(new Event(eventName), undefined, false)
		}
	}

	/**
	* @param {AnimationEvent} event - info about the event
	*/
	reportAniEvent(event) {
		let listener = this.cAniListeners.get(event.name)
		if (listener !== undefined) {
			listener[0](listener[1])
			this.cAniListeners.delete(event.name)
		}
		this.reportEventToAniList(event.name)
	}

	/**
	* @param {String} eventName - name of event
	*/
	reportAniEventName(eventName) {
		let listener = this.cAniListeners.get(eventName)
		if (listener !== undefined) {
			listener[0](listener[1])
			this.cAniListeners.delete(eventName)
		}
		this.reportEventToAniList(eventName)
	}
}

let aniScheduler = new AnimationScheduler()
shared.aniScheduler = aniScheduler


function getAniEventInfo(name, frame = null) {
	if (frame === null) {
		return name
	} else {
		return name + String(frame)
	}
}


class AnimationTaskList {
	/**
	* @param {String} trigEvent
	*/
	constructor(name, backwardMode = false, globalEndCallbackEvent = null) {
		/*if (!(backwardMode.constructor === Bool)) {
			throw 'The backwardMode parameter only accepts boolean types.'
		}*/
		this.name = name
		this.backwardTaskList = null
		this.backwardMode = backwardMode
		this.dEndEvent = globalEndCallbackEvent
		this.startEvents = new Map()
		this.endEvents = new Map()
		this.runningAnis = new Map()
		this.tid = null
		this.active = false
		this.anis = new Map()
		if (globalEndCallbackEvent !== null) {
			if (!eventDispatcher.registerEvent(globalEndCallbackEvent)) {
				if (scriptProperties.warningAutoReRegist) console.log('WARNING: Event ID "' + globalEndCallbackEvent + '" has been registered in the global event dispatcher, so beware of incorrect event listeners! ' + getCallSourceInfo())
			}
		}
	}

	setGlobalEndCallbackEvent(eventName = null) {
		this.dEndEvent = eventName
		if (eventName !== null) {
			if (!eventDispatcher.registerEvent(eventName)) {
				if (scriptProperties.warningAutoReRegist) console.log('WARNING: Event ID "' + eventName + '" has been registered in the global event dispatcher, so beware of incorrect event listeners! ' + getCallSourceInfo())
			}
		}
	}

	checkActivity(includeSubList = true) {
		if (this.active) {
			if (debugMode) {
				console.log('DEBUG: AnimationTaskList ' + this.name + ' has ' + Array.from(this.runningAnis.values()).map((data) => { return data[0].ani.name }).toString() + ' animations in activity.')
			}
			return true
		} else if (includeSubList && this.backwardTaskList !== null) {
			return this.backwardTaskList.checkActivity(true)
		} else {
			if (debugMode) {
				console.log('DEBUG: AnimationTaskList ' + this.name + ' is inactive.')
			}
			return false
		}
	}

	/**
	* @param {AnimationTaskList} taskList
	*/
	bindBackwardTaskList(taskList) {
		this.backwardTaskList = taskList
		this.backwardTaskList.runningAnis = this.runningAnis
	}

	cleanUpRunningAniList() {
		let ani;
		for ([ani] of this.runningAnis.values()) {
			if (ani.ended) {
				this.runningAnis.delete(ani.aid)
			}
		}
	}

	/**
	* @param {String} trigEventInfo
	*/
	backward(trigEventInfo) {
		if (this.backwardTaskList === null) {
			console.error('Please bind the backward AnimationTaskList first. ' + getCallSourceInfo())
			return
		}
		this.removeTask()
		this.backwardTaskList.start(trigEventInfo)
	}

	/**
	* @param {String} trigEventInfo
	*/
	start(trigEventInfo) {
		if (this.tid === null) {
			this.tid = aniScheduler._getTid()
		} else if (aniScheduler.aniTasks.has(this.tid)) {
			return
		}
		this.active = true
		if (this.backwardTaskList !== null) {
			this.backwardTaskList.removeTask()
		}
		aniScheduler.aniTasks.set(this.tid, this)
		this.cleanUpRunningAniList()
		if (this.runningAnis.size !== 0) {
			if (debugMode || logInterrupts) {
				console.log('DEBUG: ContinuousAnimation [' + Array.from(this.runningAnis.values()).map((data) => { return data[0].ani.name }).toString() + '] in AnimationTaskList ' + this.name + ' is interrupted.')
			}
			this.runningAnis.forEach(this.playAni, this)
		} else if (trigEventInfo !== null) {
			if (debugMode) {
				console.log('DEBUG: AnimationTaskList ' + this.name + ' is activated.')
			}
			let cbList = this.startEvents.get(trigEventInfo)
			if (cbList === undefined) {
				throw 'Start event "' + trigEventInfo + '" does not exist, available events: ' + Array.from(this.startEvents.keys()).toString() + ' ' + getCallSourceInfo()
			}
			cbList.forEach(this.playAniEvent, this)
			if (this.runningAnis.size === 0) {
				this.removeTask()
				this._end()
			}
		}
	}

	/**
	* @param {ContinuousAnimation} ani
	* @param {String} startEventInfo
	* @param {String} endEventInfo
	*/
	addTask(ani, startEventName = null, aniReplayable = globalReplayable, rate = 1, conditionChecker = null, __check = true) {
		let endEventName = ((this.backwardMode ? -1 : 1) * rate) <= 0 ? ani.firstEventArray[0] : ani.lastEventArray[0]
		if (__check && this.anis.has(ani.aid)) {
			console.log('WARNING: ContinuousAnimation "' + ani.ani.name + '" is re-added to AnimationTaskList "' + this.name + '". The old configuration will be discarded. ' + getCallSourceInfo())
			this.updateTask(ani, startEventName, endEventName, aniReplayable, rate)
			return
		}
		if (startEventName !== null) {
			if (startEventName.constructor === String) {
				if (!(this.startEvents.has(startEventName))) {
					this.startEvents.set(startEventName, new Map())
				}
				this.startEvents.get(startEventName).set(ani.aid, [ani, rate, aniReplayable, conditionChecker])
				startEventName = [startEventName]
			} else {
				startEventName.forEach((name) => {
					if (!(this.startEvents.has(name))) {
						this.startEvents.set(name, new Map())
					}
					this.startEvents.get(name).set(ani.aid, [ani, rate, aniReplayable, conditionChecker])
					// !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! 临时写法 !!!!!!!!!!!!!!!!!!!
					if (aniReplayable) {
						aniReplayable = false
					}
					// ---------------------------------------------------------------------------------------------------------
				}, this)
			}
		}
		if (this.endEvents.has(endEventName)) {
			console.log('WARNING: The animation endpoint event "' + endEventName + '" already exists, please use a unique event name to prevent scheduling confusion. ' + getCallSourceInfo())
		}
		this.endEvents.set(endEventName, ani)
		/*if (endEventName !== null) {
			if (!(this.endEvents.has(endEventName))) {
				this.endEvents.set(endEventName, new Set())
			}
			this.endEvents.get(endEventName).add(ani)
		}*/
		this.anis.set(ani.aid, [startEventName, endEventName])
	}

	/**
	* @param {ContinuousAnimation} ani
	* @param {String} startEventInfo
	* @param {String} endEventInfo
	*/
	updateTask(ani, startEventName = null, endEventName = null, aniReplayable = globalReplayable, rate = 1) {
		if (!this.anis.has(ani.aid)) {
			console.log('WARNING: ContinuousAnimation "' + ani.ani.name + '" does not exist in AnimationTaskList "' + this.name + '", it will be added automatically. ' + getCallSourceInfo())
			this.addTask(ani, startEventName, endEventName, aniReplayable, rate)
			return
		}
		let oldStartEventName, oldEndEventName = this.anis.get(ani.aid)
		if (oldStartEventName !== null) {
			oldStartEventName.forEach((name) => { this.startEvents.get(name).delete(ani.aid) }, this)
		}
		/*if (oldEndEventName !== null) {
			this.endEvents.get(endEventName).delete(ani.aid)
		}*/
		this.endEvents.delete(oldEndEventName)
		this.addTask(ani, startEventName, endEventName, aniReplayable, rate, false)
	}

	/**
	* @param {Array} data
	* @param {Number} aid
	*/
	playAni(data, aid) {
		let ani, rate, replayable, started;
		[ani, rate, replayable] = data
		ani.rate = rate
		if (this.backwardMode) {
			started = ani.backward(replayable)
		} else {
			started = ani.forward(replayable)
		}
		if (started) {
			if (debugMode) {
				console.log('DEBUG: Starting ContinuousAnimation ' + ani.ani.name)
			}
			this.runningAnis.set(aid, data)
		}
	}

	playAniEvent(data, aid) {
		let checker = data[3]
		if (!(checker === null || checker())) {
			return
		}
		this.playAni(data, aid)
	}

	removeTask() {
		if (this.active !== undefined) {
			this.active = false
		}
		aniScheduler.aniTasks.delete(this.tid)
	}

	handleAnimationEvent(eventName) {
		let anis = this.startEvents.get(eventName)
		if (anis !== undefined) {
			this._eName = eventName
			anis.forEach(this.playAniEvent, this)
		}
		anis = this.endEvents.get(eventName)
		if (anis !== undefined) {
			if (debugMode) {
				console.log('DEBUG: ContinuousAnimation ' + anis.ani.name + ' has ended. (' + eventName + ')')
			}
			this.runningAnis.delete(anis.aid)
			/*let ani;
			for (ani of anis) {
				ani.stop();
				this.runningAnis.delete(ani.aid)
			}*/
		}
		if (this.active && (this.runningAnis.size === 0)) {
			engine.setTimeout(this.removeTask, 20)
			this._end()
		}
	}

	_end() {
		this.active = false
		if (this.dEndEvent !== null) {
			eventDispatcher.dispatchEventToAll(new Event(this.dEndEvent), undefined, false)
		}
	}

	// Debug Tools

}


class CAniCallbacks {
	constructor (forwardStartCallback = null, forwardEndCallback = null, backwardStartCallback = null, backwardEndCallback = null) {
		this.forwardStartCallback = forwardStartCallback
		this.forwardEndCallback = forwardEndCallback
		this.backwardStartCallback = backwardStartCallback
		this.backwardEndCallback = backwardEndCallback
	}
}


shared.CAniCallbacks = CAniCallbacks


class ContinuousAnimation {
	/**
	* @param {IAnimation} ani
	* @param {Object} events
	*/
	constructor(ani, events, endCallback = null, startAtEnd = false, startFrame = 0, endFrame) {
		this.cbData = [this.setEndSignal, this]
		this.ani = ani
		this.ended = true
		this.rate = ani.rate
		this.aid = aniScheduler._getAid()
		this.startFrame = startFrame
		this.endFrame = endFrame === undefined ? ani.frameCount : endFrame
		this.ani.play()
		this.stop()
		if ((this.rate * (startAtEnd ? -1 : 1)) < 0) {
			ani.setFrame(this.endFrame - 0.01)
		} else {
			ani.setFrame(this.startFrame)
		}
		if (events === undefined) {
			throw "Please provide the event settings for " + ani.name + '. ' + getCallSourceInfo()
		} else if (!(this.startFrame in events)) {
			throw "An event needs to be bound to the first frame. " + getCallSourceInfo()
		} else if (!(this.endFrame in events)) {
			throw "An event needs to be bound to the last frame. " + getCallSourceInfo()
		}
		for (let frame in events) {
			let eventData = events[frame]
			if (!Array.isArray(eventData)) {
				events[frame] = [eventData]
			}
		}
		this.events = events
		this.firstEventArray = events[this.startFrame]
		this.lastEventArray = events[this.endFrame]
		this.dForward = startAtEnd
		this.mapperConfig = null

		if (endCallback === null) {
			this.forwardEndCallback = null
			this.backwardEndCallback = null
			this.forwardStartCallback = null
			this.backwardStartCallback = null
		} else if (endCallback.constructor === CAniCallbacks) {
			this.forwardEndCallback = endCallback.forwardEndCallback
			this.backwardEndCallback = endCallback.backwardEndCallback
			this.forwardStartCallback = endCallback.forwardStartCallback
			this.backwardStartCallback = endCallback.backwardStartCallback
		} else {
			this.forwardEndCallback = endCallback
			this.backwardEndCallback = endCallback
			this.forwardStartCallback = null
			this.backwardStartCallback = null
		}
		this.listener = new Listener(this.aid + ani.name)
	}

	setToStart(force = false) {
		if (!this.ani.cAniEnded) {
			if (force) {
				this.ani.cAniObject.stop()
			} else {
				return
			}
		}
		this.dForward = false
		this.ani.setFrame(this.startFrame)
	}

	setToEnd(force = false) {
		if (!this.ani.cAniEnded) {
			if (force) {
				this.ani.cAniObject.stop()
			} else {
				return
			}
		}
		this.dForward = true
		this.ani.setFrame(this.endFrame - 0.01)
	}

	stop() {
		if (!this.ended) {
			if (this.dForward) {
				lastEventArray.forEach(this._deleteAniListener, this)
			} else {
				firstEventArray.forEach(this._deleteAniListener, this)
			}
		}
		this.ani.cAniEnded = true
		this.ani.cAniObject = null
		if (this.mapperConfig === null) {
			this.ani.pause()
		} else {
			this.ani.stop()
		}
	}

	updateStatus() {
		// 不可使用, 未对时间轴分割功能进行适配
		let currentFrame = this.ani.getFrame()
		this.ended = (currentFrame <= 1) || (currentFrame >= this.ani.frameCount - 1)
	}

	_deleteAniListener(eventName) {
		aniScheduler.cAniListeners.delete(eventName)
	}

	_addAniListener(eventName) {
		aniScheduler.cAniListeners.set(eventName, this.cbData)
	}

	forward(replayable = globalReplayable, override = false) {
		if (this.ended !== this.ani.cAniEnded) {
			if (override) {
				this.ani.cAniObject.stop()
			} else {
				if (debugMode) {
					console.log('WARNING: The play action of ContinuousAnimation "' + this.ani.name + '"(' + this.startFrame + '~' + this.endFrame + ') has been skipped because ContinuousAnimation "' + this.ani.name + '"(' + this.ani.cAniObject.startFrame + '~' + this.ani.cAniObject.endFrame + ') is controlling this timeline. You can override the old scheduler by setting "override" to true.')
				}
				return
			}
		}
		let firstEventArray, lastEventArray;
		if (this.rate > 0) {
			firstEventArray = this.firstEventArray
			lastEventArray = this.lastEventArray
		} else {
			firstEventArray = this.lastEventArray
			lastEventArray = this.firstEventArray
		}
		if (!this.ended) {
			firstEventArray.forEach(this._deleteAniListener, this)
		} else if ((!replayable) && this.dForward) {
			if (debugMode) {
				console.log('DEBUG: Repeat forward playback of ContinuousAnimation ' + this.ani.name + ' has been blocked.')
			}
			return false
		}
		this.ani.rate = this.rate
		if (this.forwardStartCallback !== null) this.forwardStartCallback(this.listener)
		this._play()
		lastEventArray.forEach(this._addAniListener, this)
		return true
	}

	backward(replayable = globalReplayable, override = false) {
		if (this.ended !== this.ani.cAniEnded) {
			if (override) {
				this.ani.cAniObject.stop()
			} else {
				if (debugMode) {
					console.log('WARNING: The play action of ContinuousAnimation "' + this.ani.name + '"(' + this.startFrame + '~' + this.endFrame + ') has been skipped because ContinuousAnimation "' + this.ani.name + '"(' + this.ani.cAniObject.startFrame + '~' + this.ani.cAniObject.endFrame + ') is controlling this timeline. You can override the old scheduler by setting "override" to true.')
				}
				return
			}
		}
		let firstEventArray, lastEventArray;
		if (this.rate > 0) {
			firstEventArray = this.firstEventArray
			lastEventArray = this.lastEventArray
		} else {
			firstEventArray = this.lastEventArray
			lastEventArray = this.firstEventArray
		}
		if (!this.ended) {
			lastEventArray.forEach(this._deleteAniListener, this)
		} else if ((!replayable) && !this.dForward) {
			if (debugMode) {
				console.log('DEBUG: Repeat backward playback of ContinuousAnimation ' + this.ani.name + ' has been blocked.')
			}
			return false
		}
		this.ani.rate = -this.rate
		if (this.backwardStartCallback !== null) this.backwardStartCallback(this.listener)
		this._play(false)
		firstEventArray.forEach(this._addAniListener, this)
		return true
	}

	_play(forward = true) {
		this.ani.play()
		this._startAniMapper()
		if (this.ended) {
			this.ani.cAniEnded = false
			this.ani.cAniObject = this
			this.dForward = forward
			this.ended = false
			this.ani.setFrame(this.ani.rate > 0 ? this.startFrame : this.endFrame - 0.01)
		} else if (this.dForward !== forward) {
			this.dForward = forward
			let aniFrame = this.ani.getFrame()
			if (this.rate * (forward ? 1 : -1) > 0) {	// 向正
				Object.keys(this.events).forEach((eFrame) => {
					if (eFrame > aniFrame) {
						return
					}
					this.events[eFrame].forEach(aniScheduler.reportEventToAniList, aniScheduler)
				}, this)
			} else {	// 向反
				Object.keys(this.events).forEach((eFrame) => {
					if (eFrame < aniFrame) {
						return
					}
					this.events[eFrame].forEach(aniScheduler.reportEventToAniList, aniScheduler)
				}, this)
			}
		}
	}

	setEndSignal(self) {
		let ended = self.ended
		self.ended = true
		self.stop()
		self._stopAniMapper()
		if (!ended) {
			if (self.dForward) {
				if (self.forwardEndCallback !== null) self.forwardEndCallback(self.listener)
			} else {
				if (self.backwardEndCallback !== null) self.backwardEndCallback(self.listener)
			}
		}
	}

	// Animation Mapper
	bindMapper(getter, setter, data) {
		throw "This feature is not yet available"
		// setter(MapperData, getter())
		this.mapperConfig = [getter, setter, new MapperData(data)]
	}

	_startAniMapper() {
		if (this.mapperConfig !== null) {
			aniScheduler.addAniMapper(this.aid, this.mapperConfig)
		}
	}

	_stopAniMapper() {
		if (this.mapperConfig !== null) {
			aniScheduler.removeAniMapper(this.aid)
		}
	}
}

class MapperData {
	constructor(data) {
		this.data = data
		this.thisLayer = thisLayer
		this.thisObject = thisObject
	}
}

function easeInOutQuad(x) {
	return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
}

class CbData {
	constructor() {
		this.data;
		this.thisLayer = thisLayer
		this.thisObject = thisObject
	}
}

class TAnimationData {
	/**
	* @param {TransitionAnimation} srcAni
	*/
	constructor(srcAni, data = null, duration = 0, forward = true, startValue = 0, endValue = 1) {
		this.srcAni = srcAni
		this.data = data
		this.rawFactor = forward ? 0 : 1
		this.setDuration(duration)
		this.time = forward ? 0 : duration
		this.startValue = startValue
		this.endValue = endValue
		this.init = true
		this.direction = forward
		this.setDirection(forward)
		if (srcAni !== null) {
			this.delta = srcAni.deltaFunc(startValue, endValue)
			this.thisLayer = srcAni.thisLayer
			this.thisObject = srcAni.thisObject
		}
	}

	setDuration(duration) {
		this.duration = duration
		this.reciprocalDuration = 1 / duration
	}

	calcFactor() {
		return this.srcAni.easingFunc(this.rawFactor)
	}

	setDirection(forward) {
		this.direction = forward
		this._addFrametime = forward ? this._addFactor : this._subtractFactor
	}

	reverseDirection() {
		this.setDirection(!this.direction)
	}

	_addFactor(frametime) {
		if (this.init) {
			this.init = false
			return true
		}
		this.time += frametime
		this.rawFactor = this.time * this.reciprocalDuration
		if (this.rawFactor < 1) {
			return true
		} else {
			this.rawFactor = 1
			return false
		}
	}

	_subtractFactor(frametime) {
		if (this.init) {
			this.init = false
			return true
		}
		this.time -= frametime
		this.rawFactor = this.time * this.reciprocalDuration
		if (this.rawFactor > 0) {
			return true
		} else {
			this.rawFactor = 0
			return false
		}
	}

	_frameUpdate() {
		this.srcAni.setter(this, this.srcAni.interpolator(this))
	}
}

function numberDelta(a, b) {
	return b - a
}

function vectorDelta(a, b) {
	return b.subtract(a)
}

const vecAxes = ['x', 'y', 'z', 'w']

function vectorEquality(vecA, vecB) {
	let typeA = vecA.constructor
	if (typeA !== vecB.constructor) {
		return false
	}
	switch (typeA) {
		case Vec2: return _vectorEquality(vecA, vecB, 2)
		case Vec3: return _vectorEquality(vecA, vecB, 3)
		case Vec4: return _vectorEquality(vecA, vecB, 4)
	}
}

function _vectorEquality(vecA, vecB, axeNum) {
	let axe;
	for (let i = 0; i <= axeNum; i++) {
		axe = vecAxes[i]
		if (vecA[axe] !== vecB[axe]) {
			return false
		}
	}
	return true
}


/**
 * @param {TAnimationData} data
*/
function numberInterpolator(data) {
	return data.startValue + (data.delta * data.calcFactor())
}

/**
 * @param {TAnimationData} data
*/
function vectorInterpolator(data) {
	return data.startValue.add(data.delta.multiply(data.calcFactor()))
}

const interpolators = {
	'number': numberInterpolator,
	'vector': vectorInterpolator
}

const deltaFuncs = {
	'number': numberDelta,
	'vector': vectorDelta
}

const equalityCheckers = {
	'number': (a, b) => a === b,
	'vector': vectorEquality
}

class TransitionAnimation {
	/**
	* @param {IAnimation} ani
	* @param {Object} events
	*/
	constructor(interpolator = 'number', getter, setter, duration, events, endCallback = null, easingFunc = easeInOutQuad) {
		if (!(interpolator in interpolators)) {
			throw 'No interpolator named "' + interpolator + '" is available. Available interpolators: [' + Object.keys(interpolators).toString() + ']'
		}
		this.playing = false
		this.ended = true
		this.basicCbData = new CbData()
		this.thisLayer = thisLayer
		this.thisObject = thisObject
		this.getter = getter
		this.setter = setter
		this.duration = duration
		this.endCallback = endCallback
		this.interpolator = interpolators[interpolator]
		this.deltaFunc = deltaFuncs[interpolator]
		this.isEqual = equalityCheckers[interpolator]
		this.easingFunc = easingFunc
		this.aid = aniScheduler._getAid()
		this.events = events
		this.transform = this.transition
		this.trans = this.transition
		Object.keys(events).forEach((factor) => { if (factor !== 0 && factor !== 1) { console.log('WARNING: No support yet for handling animation events that are not endpoints. ' + getCallSourceInfo()) } })
	}

	setDuration(duration, updateNow) {
		this.duration = duration
		if (updateNow) {
			this.lastData.setDuration(duration)
		}
	}

	stop() {
		aniScheduler.removeInterpolator(this.aid)
	}

	checkStatus() {
		this.playing = (!this.ended) && (
			(this.lastData.direction && this.isEqual(this.lastData.startValue, targetValue))
			||
			((!this.lastData.direction) && this.isEqual(this.lastData.endValue, targetValue))
		)
		this.ended = !this.playing

	}

	transition(targetValue, data = null) {
		// this.checkStatus()
		// if (this.playing) {
		// 	this.lastData.reverseDirection()
		// }
		this.basicCbData.data = data
		if (this.isEqual(this.getter(this.basicCbData), targetValue)) {
			if (this.playing) {
				aniScheduler.removeInterpolator(this.aid)
			}
			return
		}
		this.ended = false
		this.playing = true
		this.lastData = new TAnimationData(this, data, this.duration, true, this.getter(this.basicCbData), targetValue)
		aniScheduler.addInterpolator(this.aid, this.lastData)
		this._dispatchStartEvent()
	}

	backward(targetValue, data = null) {
		throw "Method was deprecated"
		if (tips) {
			console.log('Tip: It would seem pointless to use backward mode in transition animation.')
		}
		if (this.ended && !replayable && this.dForward === false) {
			return
		}
		this._play(targetValue, false, data)
	}

	_dispatchStartEvent() {
		let eName = this.events[this.lastData.direction ? 0 : 1]
		if (eName !== undefined) {
