class EmojiScheduler {
	constructor (name, emojiAniListEndEvents) {
		this.name = name
		this.id = getEmojiInstanceID()
		this.emojiAnis = {}
		this.nextEmoji = null
		this.recentEmoji = null;
		this.recentEmojiAniList = null;
		this.emojiForwardAniActive = false;
		[this.forwardEventName, this.backwardEventName] = emojiAniListEndEvents
		eventDispatcher.registerListener(this.forwardEventName, this.name, this._emojiShown, undefined, this)
		eventDispatcher.registerListener(this.backwardEventName, this.name, this._emojiHidden, undefined, this)
	}

	addEmoji(name, aniList, isDefault=false) {
		if (isDefault) {
			this.recentEmojiAniList = aniList
			this.recentEmoji = name
		}
		this.emojiAnis[name] = aniList
	}

	switchEmoji(name, wait=false) {
		if (this.recentEmoji == name) {
			return
		}
		if (wait && this.emojiForwardAniActive) {
			this.nextEmoji = name
			return
		}
		this.emojiForwardAniActive = true
		let oldEmoji = this.recentEmojiAniList
		this.nextEmoji = null
		this.recentEmoji = name
		this.recentEmojiAniList = this.emojiAnis[name]
		this.recentEmojiAniList.start(null)
		oldEmoji.backward('hideEmoji')
	}

	_emojiHidden(e, l) {
		let self = l.data
		self.emojiForwardAniActive = false
		aniScheduler.reportEventToAniList('prevEmojiHidden')
	}

	_emojiShown(e, l) {
		let self = l.data
		self.emojiForwardAniActive = false
		if (self.nextEmoji !== null) {
			self.switchEmoji(self.nextEmoji)
		}
	}
}

