/*

	Auto Sway

*/

let SwayParamsRecord = new Map()

class SwayParams {

	/**
	 * @param {Number} base
	 * @param {Number} increment
	 * @param {Number} exponentiation
	 */
	constructor (base, increment, exponentiation=1, recordName=null, replace=true) {
		this.name = recordName
		if (recordName !== null) {
			if (replace || !SwayParamsRecord.has(this.name)){
				SwayParamsRecord.set(this.name, this)
			}
		}
		this.base = base
		this.increment = increment
		this.exponentiation = exponentiation
	}

	/**
	 * @param {Number} index
	 * @param {Number} factor
	 * @return {Number}
	 */
	calcNodeParam(index, factor = 1) {
		return this.base + Math.pow(this.increment * index, this.exponentiation) * factor
	}
}

shared.SwayParamsClass = SwayParams

let delayGroups = new Map()

class SwayDelayGroup extends SwayParams{

	/**
	 * @param {String} name
	 * @param {Number} base
	 * @param {Number} increment
	 * @param {Number} exponentiation
	 */
	constructor (name, base, increment, exponentiation=1, replace=true) {
		super(base, increment, exponentiation)
		this.name = name
		if (replace || !delayGroups.has(this.name)){
			delayGroups.set(this.name, this)
		}
	}

	/**
	 * @param {Number} index
	 * @param {Number} factor
	 */
	calcDelay(index, factor=1) {
		return this.calcNodeParam(index, factor)
	}
}

shared.SwayDelayGroupClass = SwayDelayGroup

/**
 * @param {Number | [string] | null} aniLayers
 * @param {String} timeoffsetParamsName
 * @param {Number} timeoffsetFactor
 * @param {String} strengthParamsName
 * @param {Number} strengthFactor
 * @param {Number} rate
 * @param {String} delayGroupName
 * @param {Number} delayGroupIndex
 * @param {Number} delayFactor
 */
function startSwayAniLayerListFromRecord(aniLayers=null, timeoffsetParamsName, timeoffsetFactor=1, strengthParamsName, strengthFactor=1, rate=1, delayGroupName=null, delayGroupIndex=1, delayFactor=1, initIndex=0, overrideAniCount=null) {
	let timeoffsetParams = SwayParamsRecord.get(timeoffsetParamsName)
	if (timeoffsetParams === undefined) {
		throw 'Preset sway parameter does not exist: ' + timeoffsetParamsName + '. ' + getCallSourceInfo()
	}
	let strengthParams = SwayParamsRecord.get(strengthParamsName)
	if (strengthParams === undefined) {
		throw 'Preset sway parameter does not exist: ' + strengthParamsName + '. ' + getCallSourceInfo()
	}
	startSwayAniLayerList(aniLayers, timeoffsetParams, timeoffsetFactor, strengthParams, strengthFactor, rate, delayGroupName, delayGroupIndex, delayFactor, initIndex, overrideAniCount)
}

shared.startSwayAniLayerListFromRecord = startSwayAniLayerListFromRecord

/**
 * @param {Number | [string] | null} aniLayers
 * @param {SwayParams} timeoffsetParams
 * @param {Number} timeoffsetFactor
 * @param {SwayParams} strengthParams
 * @param {Number} strengthFactor
 * @param {Number} rate
 * @param {String} delayGroupName
 * @param {Number} delayGroupIndex
 * @param {Number} delayFactor
 */
function startSwayAniLayerList(aniLayers=null, timeoffsetParams, timeoffsetFactor=1, strengthParams, strengthFactor=1, rate=1, delayGroupName=null, delayGroupIndex=1, delayFactor=1, initIndex=0, overrideAniCount=null) {
	if (!'getAnimationLayer' in thisLayer) {
		throw 'You can only use "startSwayAniLayerList" in image layers. ' + getCallSourceInfo()
	}
	let basicDelay;
	if (delayGroupName === null) {
		basicDelay = 0
	} else {
		let delayGroup = delayGroups.get(delayGroupName)
		if (delayGroup === undefined) {
			if (tips) {
				console.log('TIP: The specified Delay Group "' + delayGroupName + '" does not exist. A linear incremental group has been created automatically. It is recommended to manually create the required Delay Group to manage the project more consistently. ' + getCallSourceInfo())
			}
			basicDelay = new SwayDelayGroup(delayGroupName, 0, 1).calcDelay(delayGroupIndex, delayFactor)
		} else {
			basicDelay = delayGroup.calcDelay(delayGroupIndex, delayFactor)
		}
	}
	if (aniLayers === null) {
		let aniCount = overrideAniCount === null ? thisLayer.getAnimationLayerCount() : overrideAniCount
		for (i = 0; i < aniCount; i++) {
			initSwayAni(thisLayer.getAnimationLayer(i), timeoffsetParams, timeoffsetFactor, strengthParams, strengthFactor, aniCount, i + initIndex, rate, basicDelay)
		}
	} else if (aniLayers instanceof Array && aniLayers.length === 2) {
		let aniCount = overrideAniCount === null ? aniLayers[1] - aniLayers[0] + 1 : overrideAniCount
		for (i = aniLayers[0]; i <= aniLayers[1]; i++) {
			initSwayAni(thisLayer.getAnimationLayer(String(i)), timeoffsetParams, timeoffsetFactor, strengthParams, strengthFactor, aniCount, i + initIndex, rate, basicDelay)
		}
	} else if (aniLayers instanceof Number) {
		for (i = 0; i < aniLayers; i++) {
			initSwayAni(thisLayer.getAnimationLayer(i), timeoffsetParams, timeoffsetFactor, strengthParams, strengthFactor, (overrideAniCount === null ? aniLayers : overrideAniCount), i + initIndex, rate, basicDelay)
		}
	} else if (aniLayers instanceof Array && aniLayers[0] instanceof String) {
		let aniCount = overrideAniCount === null ? aniLayers.length() : overrideAniCount
		for (i = 0; i < aniCount; i++) {
			initSwayAni(thisLayer.getAnimationLayer(aniLayers[i]), timeoffsetParams, timeoffsetFactor, strengthParams, strengthFactor, aniCount, i + initIndex, rate, basicDelay)
		}
	} else {
		throw 'Incorrect type of parameter "aniLayers". ' + getCallSourceInfo()
	}
}


/**
 * @param {IAnimationLayer} aniLayer
 * @param {SwayParams} timeoffsetParams
 * @param {Number} timeoffsetFactor
 * @param {SwayParams} strengthParams
 * @param {Number} strengthFactor
 * @param {Number} boneCount
 * @param {Number} index
 * @param {Number} rate
 */
function initSwayAni(aniLayer, timeoffsetParams, timeoffsetFactor=1, strengthParams, strengthFactor=1, boneCount, index, rate, extraDelay=0) {
	aniLayer.play()
	aniLayer.setFrame(aniLayer.frameCount * -((timeoffsetParams.calcNodeParam(index, timeoffsetFactor / boneCount) + extraDelay) % 1))
	aniLayer.blend = strengthParams.calcNodeParam(index, strengthFactor)
	aniLayer.rate = rate
	aniLayer.visible = true
}


