/*

	User properties change detection

*/


shared.userPropertyCategories = new Map()

shared.STARTS_WITH = 0
shared.END_WITH = 1

const matchMethods = [
	(propertyKey, targetText) => propertyKey.startsWith(targetText),
	(propertyKey, targetText) => propertyKey.endsWith(targetText)
]

let boundUserProperties = {}

function bindUserProperty(userProperty, category) {
	if (userProperty in boundUserProperties) {
		boundUserProperties[userProperty].push(category)
	} else {
		boundUserProperties[userProperty] = [category]
	}
}

class UserPropertyCategory {
	constructor(name, matcher, targetText) {
		this.name = name
		this.matcher = matcher
		this.targetText = targetText
		this.changedUserProperties = {}
		this.userPropertyKeyList = []
		this.changed = true		// 初次载入时一律视为已变更
		this._bindUserProperties()
	}

	_bindUserProperties() {
		Object.keys(engine.userProperties).forEach((userProperty) => {
			if (this.matcher(userProperty, this.targetText)) {
				this.userPropertyKeyList.push(userProperty)
				bindUserProperty(userProperty, this)
			}
		})
		if (debugMode) {
			console.log('DEBUG: UserPropertyCategory "' + this.name + '" binds the following user properties: ' + this.userPropertyKeyList.toString())
		}
	}

	addChangedUserProperty(userProperty, value) {
		this.changedUserProperties[userProperty] = value
		this.changed = true
	}

	clearChangeRecord() {
		this.changedUserProperties = {}
		this.changed = false
	}
}

/**
 * @param {String} name
 * @param {Number} matchMethod
 * @param {String} targetText
 */
function registerUserPropertyCategory(name, matchMethod, targetText) {
	if (shared.userPropertyCategories.has(name)) {
		throw 'Duplicate UserPropertyCategory "' + name + '". ' + getCallSourceInfo()
	}
	let userPropertyCategory = new UserPropertyCategory(name, matchMethods[matchMethod], targetText)
	shared.userPropertyCategories.set(name, userPropertyCategory)
	return userPropertyCategory
}

/**
 * @param {String} name
 */
function getUserPropertyCategory(name) {
	let userPropertyCategory = shared.userPropertyCategories.get(name)
	if (userPropertyCategory === undefined) {
		throw 'Non-existent UserPropertyCategory "' + name + '". ' + getCallSourceInfo()
	} else {
		return userPropertyCategory
	}
}

shared.registerUserPropertyCategory = registerUserPropertyCategory
shared.getUserPropertyCategory = getUserPropertyCategory

function syncChangedUserProperties(changedUserProperties) {
	Object.keys(changedUserProperties).forEach((changedUserProperty) => {
		if (!(changedUserProperty in boundUserProperties)) return
		boundUserProperties[changedUserProperty].forEach(category => {
			category.addChangedUserProperty(changedUserProperty, changedUserProperties[changedUserProperty])
		})
	})
	if (debugMode) {
		shared.userPropertyCategories.forEach(category => {
			if (!category.changed) return
			console.log('DEBUG: UserPropertyCategory "' + category.name + '" has been updated.')
		})
	}
}

function clearChangedUserPropertyRecord() {
	shared.userPropertyCategories.forEach(category => {
		category.clearChangeRecord()
	})
}


/*

	WPE Events

*/


let checkChangedUserProperties = false

/**
 * @param {Object} changedUserProperties - only includes user properties that were recently changed!
 */
export function applyUserProperties(changedUserProperties) {
	if (!checkChangedUserProperties) {
		checkChangedUserProperties = true
		return
	}
	clearChangedUserPropertyRecord()
	syncChangedUserProperties(changedUserProperties)
}

